-- Redaction retains identity, not an apparently valid replacement body.
CREATE TABLE evidence_redactions(digest TEXT PRIMARY KEY REFERENCES evidence(digest),record TEXT NOT NULL CHECK(json_valid(record)),record_digest TEXT NOT NULL);
CREATE TRIGGER evidence_redaction_no_update BEFORE UPDATE ON evidence_redactions BEGIN SELECT RAISE(ABORT,'redaction tombstones immutable'); END;
CREATE TRIGGER evidence_redaction_no_delete BEFORE DELETE ON evidence_redactions BEGIN SELECT RAISE(ABORT,'redaction tombstones retained'); END;
CREATE TRIGGER redacted_body_no_update BEFORE UPDATE ON evidence WHEN EXISTS(SELECT 1 FROM evidence_redactions WHERE digest=OLD.digest) AND (NEW.digest!=OLD.digest OR NEW.content!='' OR NEW.media_type!=OLD.media_type OR NEW.provenance!=OLD.provenance OR NEW.recorded_at!=OLD.recorded_at) BEGIN SELECT RAISE(ABORT,'redacted evidence cannot be rehydrated'); END;
CREATE TRIGGER redacted_body_no_delete BEFORE DELETE ON evidence WHEN EXISTS(SELECT 1 FROM evidence_redactions WHERE digest=OLD.digest) BEGIN SELECT RAISE(ABORT,'redacted evidence identity retained'); END;
CREATE TABLE retention_invalidations(sequence INTEGER PRIMARY KEY AUTOINCREMENT,digest TEXT NOT NULL REFERENCES evidence_redactions(digest),case_id TEXT NOT NULL REFERENCES cases(id),recorded_at TEXT NOT NULL,UNIQUE(digest,case_id));
CREATE INDEX retention_case_epoch ON retention_invalidations(case_id,sequence);
CREATE TRIGGER retention_invalidation_no_update BEFORE UPDATE ON retention_invalidations BEGIN SELECT RAISE(ABORT,'proof invalidation immutable'); END;
CREATE TRIGGER retention_invalidation_no_delete BEFORE DELETE ON retention_invalidations BEGIN SELECT RAISE(ABORT,'proof invalidation retained'); END;
CREATE TABLE retention_proofs(kind TEXT NOT NULL,identity TEXT NOT NULL,case_id TEXT NOT NULL REFERENCES cases(id),epoch INTEGER NOT NULL,PRIMARY KEY(kind,identity));
CREATE TRIGGER retention_proof_no_update BEFORE UPDATE ON retention_proofs BEGIN SELECT RAISE(ABORT,'proof epoch immutable'); END;
CREATE TRIGGER retention_proof_no_delete BEFORE DELETE ON retention_proofs BEGIN SELECT RAISE(ABORT,'proof epoch retained'); END;
INSERT INTO retention_proofs SELECT 'candidate',id,case_id,0 FROM repair_candidates;
CREATE TRIGGER repair_candidates_proof_epoch AFTER INSERT ON repair_candidates BEGIN INSERT INTO retention_proofs SELECT 'candidate',NEW.id,NEW.case_id,(SELECT COALESCE(MAX(sequence),0) FROM retention_invalidations WHERE case_id=NEW.case_id) WHERE NOT EXISTS(SELECT 1 FROM retention_proofs WHERE kind='candidate' AND identity=NEW.id); END;
