INSERT INTO retention_proofs SELECT 'recovery_plan',json_extract(record,'$.plan.id'),case_id,0 FROM recovery_state WHERE json_extract(record,'$.plan.id') IS NOT NULL;
CREATE TRIGGER recovery_plan_proof_insert AFTER INSERT ON recovery_state WHEN json_extract(NEW.record,'$.plan.id') IS NOT NULL BEGIN INSERT INTO retention_proofs SELECT 'recovery_plan',json_extract(NEW.record,'$.plan.id'),NEW.case_id,(SELECT COALESCE(MAX(sequence),0) FROM retention_invalidations WHERE case_id=NEW.case_id) WHERE NOT EXISTS(SELECT 1 FROM retention_proofs WHERE kind='recovery_plan' AND identity=json_extract(NEW.record,'$.plan.id')); END;
CREATE TRIGGER recovery_plan_proof_update AFTER UPDATE ON recovery_state WHEN json_extract(NEW.record,'$.plan.id') IS NOT NULL BEGIN INSERT INTO retention_proofs SELECT 'recovery_plan',json_extract(NEW.record,'$.plan.id'),NEW.case_id,(SELECT COALESCE(MAX(sequence),0) FROM retention_invalidations WHERE case_id=NEW.case_id) WHERE NOT EXISTS(SELECT 1 FROM retention_proofs WHERE kind='recovery_plan' AND identity=json_extract(NEW.record,'$.plan.id')); END;
